INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13126, 'koKR', 'Wspólny front', 'Przyjmij, proszę, naszą wdzięczność.$b$bTy i twoi przyjaciele odnieśliście sukces tam, gdzie my zawiedliśmy – pokonaliście Drakosa. Dalej jednak będziemy musieli połączyć siły.$b$bNad nami Varos kryje się za nieprzeniknioną tarczą. Aby do niego dotrzeć, musisz zniszczyć konstrukty wirówki, które zasilają jego tarczę. I tu do akcji wkraczamy ja i moi przyjaciele...$b$bKażde z nas może wam dać smoki ze swojego stada. Tylko z pomocą tych smoków zdołacie odsłonić Varosa.', 'Belgaristrasz chce, abyś $gzniszczył:zniszczyła; 10 konstruktów wirówki, by zdjąć tarczę Varosa. Następnie musisz pokonać Varosa Obłokokroczącego.', '', 'Wróć do wizerunku Belgaristrasza w Okulusie.', 'Zniszczone konstrukty wirówki', 'Pokonany Varos Obłokokroczący', '', '', 0),
(13127, 'koKR', 'Władca Magów Urom', 'Między nami a naszym ostatecznym celem stoi już tylko jedna przeszkoda, $N. Nazywa się Urom.$b$bCzeka na nas wyżej, strzegąc trzeciego pierścienia. Strzeż się jego potężnych czarów, przyjacielu. To groźny przeciwnik, który z pewnością wystawi twoje umiejętności na próbę.$b$bPokonaj go. Niech zapłaci za zdradzieckie przymierze z wrogiem!', 'Belgaristrasz chce, abyś $gpokonał:pokonała; Władcę Magów Uroma w Okulusie.', '', 'Wróć do wizerunku Belgaristrasza w Okulusie.', 'Pokonany Władca Magów Urom', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13126, 'koKR', 'Stało się, jak miałem nadzieję. Dobrze nam się współpracuje.$b$bOby nasza dalsza współpraca wystarczyła, by pokonać wyzwania, które jeszcze nas czekają!', 0),
(13127, 'koKR', 'Zwycięstwo jest w zasięgu ręki, przyjacielu.$b$bSkup się, bo teraz nadchodzi prawdziwa próba.', 0),
(13240, 'koKR', '<Arcymag kiwa głową, zanim jeszcze zdążysz cokolwiek powiedzieć.>$b$bWiem. $GZniszczyłeś:Zniszczyłaś; konstrukty, tak jak przewidziałem, i dzięki temu $gmogłeś:mogłaś; stanąć do walki z Varosem Obłokokroczącym.$b$bZnakomita robota, $N!', 0),
(13247, 'koKR', 'Dziękuję, $N. Zbadanie tego stroika powinno nam lepiej pokazać, jak Malygos manipuluje liniami mocy.$b$bJeśli znajdziemy słabość w jego metodach, być może zdołamy ją wykorzystać i odwrócić losy walki.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13126, 'koKR', 'A więc stało się!', 0),
(13127, 'koKR', 'Czy Władca Magów Urom został pokonany?', 0),
(13240, 'koKR', 'Wyczuwam, że nie $gzniszczyłeś:zniszczyłaś; jeszcze wszystkich konstruktów.', 0),
(13247, 'koKR', 'Czy strażnik linii mocy został pokonany, $N?$b$bNie muszę ci chyba przypominać, że Malygos próbuje powstrzymać używanie wszelkiej magii na świecie, a Błękitne Stado zabija każdego, kto potrafi nią władać i nie chce przejść na ich stronę?', 0);
