INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27411, 'koKR', 'Cóż tu mamy... tych, którzy sprzeciwiają się Tkaczowi Zaklęć? Pozbawionych przezorności i zrozumienia. Jak mam wam otworzyć oczy? Malygos ratuje świat przed nim samym! Bah! Nie jesteście warci mojego czasu!', '', 0),
(27412, 'koKR', 'Biedni, ślepi głupcy!', '', 0),
(27413, 'koKR', 'Najwyraźniej moje zwierzątka zawiodły. Może przyda się kolejny pokaz.', '', 0),
(27414, 'koKR', 'Wciąż walczycie. Wciąż kurczowo trzymacie się błędnych zasad. Jeśli przeżyjecie, znajdziecie mnie w środkowym pierścieniu.', '', 0),
(27903, 'koKR', '%s zaczyna rzucać Wzmocnioną tajemną eksplozję!', '', 0),
(31793, 'koKR', 'Więźniowie nie odzyskają wolności! Słowo Malygosa jest prawem!', '', 0),
(31794, 'koKR', 'Drżyjcie, robaki!', '', 0),
(31795, 'koKR', 'Zmiażdżę was!', '', 0),
(31796, 'koKR', 'Umiesz latać?', '', 0),
(31797, 'koKR', 'Za późno na ucieczkę!', '', 0),
(31798, 'koKR', 'Zbliżcie się...', '', 0),
(31799, 'koKR', 'Nikt nie ucieknie!', '', 0),
(31800, 'koKR', 'Skazuję cię na śmierć!', '', 0),
(31801, 'koKR', 'Stosowna kara.', '', 0),
(31802, 'koKR', 'Wyrok wykonany!', '', 0),
(31803, 'koKR', 'Kolejna ofiara wojny!', '', 0),
(31804, 'koKR', 'Wojna... trwa dalej.', '', 0),
(31812, 'koKR', 'Intruzi, wasze zwycięstwo będzie krótkotrwałe. Jestem dowódca Varos Obłokokroczący. Moje smoki panują nad niebem i chronią ten kanał. Osobiście dopilnuję, by Okulus nie wpadł w wasze ręce!', '', 0),
(31813, 'koKR', 'Nie będzie litości!', '', 0),
(31814, 'koKR', 'Rozwalcie ich! Zniszczcie ich!', '', 0),
(31819, 'koKR', 'Są... zbyt silni! Nie doceniłem ich... wytrwałości.', '', 0),
(31829, 'koKR', 'Przedsmak... tylko mały przedsmak... mocy Tkacza Zaklęć!', '', 0),
(31830, 'koKR', 'Tyle niestabilnej energii... ale warto zaryzykować, by was zniszczyć!', '', 0),
(31831, 'koKR', 'Gdybyście tylko rozumieli!', '', 0),
(31832, 'koKR', 'Teraz widzicie? Widzicie?!', '', 0),
(31833, 'koKR', 'Godne pożałowania, ale konieczne.', '', 0),
(31834, 'koKR', 'Wszystko, co zrobiłem... zrobiłem dla Azeroth...', '', 0),
(33077, 'koKR', '%s wzywa lazurowego kapitana pierścienia!', '', 0);
